            <td><span class="cf-spec-rarity-badge cf-rarity-${String(rarity).toLowerCase()}">${rIcon}${rarity} · ${rec.rarity_full_en || "Super Rare"} (${rec.rarity_full_jp || "スーパーレア"})</span></td>
